-- Esquema de la BD principal (capa analítica). Lo genera pipeline/p10_capa_analitica.py; no editar a mano.
-- crear_bd_analitica.py lo usa para crear las tablas con sus llaves, cargarlas desde parquet y crear las vistas.

-- @@ tabla cat_certificado_origen
CREATE TABLE cat_certificado_origen(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_clase_exportador
CREATE TABLE cat_clase_exportador(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_forma_pago
CREATE TABLE cat_forma_pago(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_lugar_salida
CREATE TABLE cat_lugar_salida(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_modalidad_exportacion
CREATE TABLE cat_modalidad_exportacion(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_modo_transporte
CREATE TABLE cat_modo_transporte(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_regimen_can
CREATE TABLE cat_regimen_can(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_tipo_identificacion
CREATE TABLE cat_tipo_identificacion(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_tipo_usuario
CREATE TABLE cat_tipo_usuario(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla cat_unidad_fisica
CREATE TABLE cat_unidad_fisica(CODIGO VARCHAR, DESCRIPCION VARCHAR, FUENTE VARCHAR, CONFIANZA VARCHAR, NOTA VARCHAR, PRIMARY KEY(CODIGO));

-- @@ tabla diccionario_datos
CREATE TABLE diccionario_datos(TABLA VARCHAR, COLUMNA VARCHAR, TIPO VARCHAR, DESCRIPCION VARCHAR, ORIGEN_O_REGLA VARCHAR, PRIMARY KEY(TABLA, COLUMNA));

-- @@ tabla dim_aduana
CREATE TABLE dim_aduana(COD_ADUANA VARCHAR, ADUANA VARCHAR, PRIMARY KEY(COD_ADUANA));

-- @@ tabla dim_declarante
CREATE TABLE dim_declarante(NIT_DECLARANTE VARCHAR, RAZON_SOCIAL_DECLARANTE VARCHAR, N_VARIANTES_NOMBRE BIGINT, PRIMARY KEY(NIT_DECLARANTE));

-- @@ tabla dim_departamento
CREATE TABLE dim_departamento(COD_DEPTO VARCHAR, DEPARTAMENTO VARCHAR, ES_ANTIOQUIA BOOLEAN, PRIMARY KEY(COD_DEPTO));

-- @@ tabla dim_pais
CREATE TABLE dim_pais(COD_PAIS VARCHAR, PAIS VARCHAR, COD_ISO2 VARCHAR, COD_NUMERICO_M49 VARCHAR, TIPO_DESTINO VARCHAR, APARECE_COMO_DESTINO BOOLEAN, APARECE_COMO_BANDERA BOOLEAN, PRIMARY KEY(COD_PAIS));

-- @@ tabla dim_subpartida
CREATE TABLE dim_subpartida(SUBPARTIDA VARCHAR, CAPITULO VARCHAR, PARTIDA VARCHAR, SUBPARTIDA_SA6 VARCHAR, SECTOR_EXPORTACION VARCHAR, ES_MINERO_ENERGETICO BOOLEAN, ES_AGRICOLA_MADR BOOLEAN, PRODUCTO_AGRICOLA_MADR VARCHAR, TRADICION_AGRICOLA_MADR VARCHAR, DESCRIPCION_PARTIDA_MADR VARCHAR, PRIMARY KEY(SUBPARTIDA));

-- @@ tabla dim_zona_franca
CREATE TABLE dim_zona_franca(COD_ZONA_FRANCA VARCHAR, ZONA_FRANCA VARCHAR, NOMBRES_EN_FUENTE VARCHAR, PRIMARY KEY(COD_ZONA_FRANCA));

-- @@ tabla hechos_analitica
CREATE TABLE hechos_analitica(ID_REGISTRO BIGINT, PERIODO DATE, ANIO SMALLINT, MES TINYINT, FECHA_DECLARACION DATE, NUMERO_FORMULARIO VARCHAR, NUMERO_SERIE INTEGER, TIPO_DESPACHO VARCHAR, TIPO_DATOS VARCHAR, TIPO_EMBARQUE VARCHAR, NUM_DECLARACION_ANTERIOR VARCHAR, PERIODO_DECLARACION_ANTERIOR DATE, NUM_DECLARACION_PRECEDENTE VARCHAR, PERIODO_DECLARACION_PRECEDENTE DATE, NUM_AUTORIZACION_EMBARQUE VARCHAR, PERIODO_AUTORIZACION_EMBARQUE DATE, NIT_EXPORTADOR VARCHAR, TIPO_IDENTIFICACION VARCHAR, ES_PERSONA_NATURAL BOOLEAN, FLAG_RAZON_SOCIAL_ENMASCARADA BOOLEAN, CLASE_EXPORTADOR VARCHAR, TIPO_USUARIO VARCHAR, DIRECCION_DECLARADA VARCHAR, COD_MPIO_DIRECCION_DECLARADA VARCHAR, DIRECCION_DECLARADA_EN_ANTIOQUIA BOOLEAN, NIT_DECLARANTE VARCHAR, CIUDAD_DESTINATARIO VARCHAR, COD_PAIS_DESTINO VARCHAR, ES_DESTINO_ZONA_FRANCA BOOLEAN, COD_ZONA_FRANCA_DESTINO VARCHAR, COD_ADUANA_DESPACHO VARCHAR, COD_ADUANA_SALIDA VARCHAR, COD_LUGAR_SALIDA VARCHAR, COD_DEPTO_PROCEDENCIA VARCHAR, COD_DEPTO_ORIGEN VARCHAR, ORIGEN_MERCANCIA_ANTIOQUIA BOOLEAN, COD_MODO_TRANSPORTE VARCHAR, COD_PAIS_BANDERA VARCHAR, COD_MODALIDAD_EXPORTACION VARCHAR, COD_REGIMEN_CAN VARCHAR, FORMA_PAGO VARCHAR, TIPO_CERTIFICADO_ORIGEN VARCHAR, SISTEMAS_ESPECIALES BOOLEAN, EXPORTACION_EN_TRANSITO BOOLEAN, COD_MONEDA_TRANSACCION VARCHAR, SUBPARTIDA VARCHAR, COD_UNIDAD_FISICA VARCHAR, CANTIDAD_UNIDADES_FISICAS DOUBLE, PESO_BRUTO_KGS DOUBLE, PESO_NETO_KGS DOUBLE, VALOR_FOB_USD DOUBLE, VALOR_FOB_COP DOUBLE, VALOR_AGREGADO_NACIONAL_USD DOUBLE, VALOR_FLETES_USD DOUBLE, VALOR_SEGUROS_USD DOUBLE, VALOR_OTROS_GASTOS_USD DOUBLE, FLAG_PESO_CERO BOOLEAN, FLAG_REGISTRO_IDENTICO BOOLEAN, ARCHIVO_FUENTE VARCHAR, NIVEL_REFERENCIA_PRECIO_KG VARCHAR, RAZON_PRECIO_KG_VS_MEDIANA FLOAT, FLAG_PRECIO_KG_ATIPICO BOOLEAN, NIVEL_REFERENCIA_PRECIO_UNIDAD VARCHAR, RAZON_PRECIO_UNIDAD_VS_MEDIANA FLOAT, FLAG_CANTIDAD_ATIPICA BOOLEAN, FLAG_ATIPICO BOOLEAN, FLAG_POSIBLE_ERROR_FOB BOOLEAN, PESO_NETO_KGS_AJUSTADO DOUBLE, PESO_BRUTO_KGS_AJUSTADO DOUBLE, CANTIDAD_UNIDADES_FISICAS_AJUSTADA DOUBLE, METODO_AJUSTE VARCHAR, PRIMARY KEY(ID_REGISTRO));

-- @@ tabla info_bd_depurada
CREATE TABLE info_bd_depurada(CLAVE VARCHAR, VALOR VARCHAR, PRIMARY KEY(CLAVE));

-- @@ tabla info_capa
CREATE TABLE info_capa(CLAVE VARCHAR, VALOR VARCHAR, PRIMARY KEY(CLAVE));

-- @@ tabla log_depuracion
CREATE TABLE log_depuracion(PASO BIGINT, ETAPA VARCHAR, REGLA VARCHAR, FILAS_AFECTADAS DOUBLE, FOB_USD_AFECTADO DOUBLE, DETALLE VARCHAR, PRIMARY KEY(PASO));

-- @@ tabla log_preparacion
CREATE TABLE log_preparacion(PASO INTEGER PRIMARY KEY, ETAPA VARCHAR, REGLA VARCHAR, FILAS_AFECTADAS DOUBLE, FOB_USD_AFECTADO DOUBLE, DETALLE VARCHAR);

-- @@ tabla ref_dane_publicaciones
CREATE TABLE ref_dane_publicaciones(PERIODO_REFERENCIA VARCHAR, PERIODO_DESDE DATE, PERIODO_HASTA DATE, DANE_FOB_MUSD DECIMAL(6,1), FUENTE VARCHAR, URL VARCHAR, PRIMARY KEY(PERIODO_REFERENCIA));

-- @@ tabla ref_madr_agricola_anual
CREATE TABLE ref_madr_agricola_anual(ANIO SMALLINT, MESES TINYINT, MADR_AGRICOLA_NACIONAL_MUSD DOUBLE, MADR_AGRICOLA_ANTIOQUIA_MUSD DOUBLE, PRIMARY KEY(ANIO));

-- @@ tabla ref_mincit_trimestral
CREATE TABLE ref_mincit_trimestral(TRIMESTRE VARCHAR, MINCIT_TOTAL_MUSD DOUBLE, MINCIT_NME_MUSD DOUBLE, PRIMARY KEY(TRIMESTRE));

-- @@ tabla relaciones_llaves
CREATE TABLE relaciones_llaves(TABLA VARCHAR, COLUMNAS VARCHAR, TABLA_REFERENCIA VARCHAR, COLUMNAS_REFERENCIA VARCHAR, TIPO VARCHAR, FILAS_HUERFANAS INTEGER);

-- @@ tabla dim_municipio
CREATE TABLE dim_municipio(COD_MPIO VARCHAR, MUNICIPIO VARCHAR, COD_DEPTO VARCHAR, PRIMARY KEY(COD_MPIO), FOREIGN KEY (COD_DEPTO) REFERENCES dim_departamento(COD_DEPTO));

-- @@ tabla map_ciudad_destinatario
CREATE TABLE map_ciudad_destinatario(CIUDAD_DESTINATARIO VARCHAR, COD_PAIS_DESTINO VARCHAR, CIUDAD_NORMALIZADA VARCHAR, N_LINEAS BIGINT, PRIMARY KEY(CIUDAD_DESTINATARIO, COD_PAIS_DESTINO), FOREIGN KEY (COD_PAIS_DESTINO) REFERENCES dim_pais(COD_PAIS));

-- @@ tabla dim_exportador_analitica
CREATE TABLE dim_exportador_analitica(RANKING_NACIONAL_FOB BIGINT, RANKING_ANTIOQUIA_FOB BIGINT, NIT VARCHAR, RAZON_SOCIAL VARCHAR, VINCULO_ANTIOQUIA VARCHAR, EMPRESA_ANTIOQUENA BOOLEAN, ES_EXPORTADOR_ANTIOQUENO BOOLEAN, NOMBRES_EN_FUENTE VARCHAR, RAZON_SOCIAL_RUES VARCHAR, CLASE_EXPORTADOR VARCHAR, CLASE_EXPORTADOR_DESC VARCHAR, CAMARA_COMERCIO VARCHAR, MATRICULA VARCHAR, CIIU_PRINCIPAL_RUES VARCHAR, CIIU_SECUNDARIO_RUES VARCHAR, ORGANIZACION_JURIDICA VARCHAR, FECHA_MATRICULA DATE, ULTIMO_ANO_RENOVADO SMALLINT, ESTADO_MATRICULA VARCHAR, TIENE_MATRICULA_ACTIVA_EN_ANTIOQUIA BOOLEAN, COD_MPIO_DIAN_DIRECCION_PROPIA VARCHAR, MUNICIPIO_DIAN_DIRECCION_PROPIA VARCHAR, DEPTO_DIAN_DIRECCION_PROPIA VARCHAR, COD_DEPTO_ORIGEN_PRINCIPAL VARCHAR, DEPTO_ORIGEN_PRINCIPAL_MERCANCIA VARCHAR, SECTOR_EXPORTADOR_PRINCIPAL VARCHAR, PCT_FOB_MINERO_ENERGETICO DOUBLE, PCT_FOB_AGRICOLA_MADR DOUBLE, PRODUCTO_AGRICOLA_PRINCIPAL_MADR VARCHAR, FOB_USD_2024 DOUBLE, FOB_USD_2025 DOUBLE, FOB_USD_2026 DOUBLE, FOB_USD_TOTAL DOUBLE, FOB_USD_ORIGEN_ANTIOQUIA DOUBLE, PCT_FOB_ORIGEN_ANTIOQUIA DOUBLE, PCT_FOB_DESTINO_ZONA_FRANCA DOUBLE, PESO_NETO_KGS_TOTAL DOUBLE, N_REGISTROS BIGINT, N_DECLARACIONES BIGINT, N_MESES_CON_EXPORTACION BIGINT, PRIMER_MES VARCHAR, ULTIMO_MES VARCHAR, N_PAISES_DESTINO BIGINT, TOP3_PAISES_DESTINO VARCHAR, N_SUBPARTIDAS BIGINT, TOP5_SUBPARTIDAS VARCHAR, CAPITULO_ARANCEL_PRINCIPAL VARCHAR, ADUANA_SALIDA_PRINCIPAL VARCHAR, MODO_TRANSPORTE_PRINCIPAL VARCHAR, SS_MACROSECTOR VARCHAR, SS_CIIU VARCHAR, SS_SUPERVISOR VARCHAR, SS_DEPARTAMENTO_DOMICILIO VARCHAR, SS_CIUDAD_DOMICILIO VARCHAR, SS_INGRESOS_OPERACIONALES_BILLONES_COP DOUBLE, SS_TOTAL_ACTIVOS_BILLONES_COP DOUBLE, SS_ANO_CORTE SMALLINT, PROVEEDOR_ESTADO_SECOP_II BOOLEAN, SECOP_N_CONTRATOS INTEGER, SECOP_VALOR_CONTRATOS_COP DOUBLE, SECOP_PRIMERA_FIRMA DATE, SECOP_ULTIMA_FIRMA DATE, SECOP_ES_PYME VARCHAR, SECOP_N_ENTIDADES INTEGER, FUENTE_DOMICILIO VARCHAR, EXPORTADOR_2024_MIN_1000USD BOOLEAN, EXPORTADOR_2025_MIN_1000USD BOOLEAN, EXPORTADOR_2026_MIN_1000USD BOOLEAN, FLAG_SECOP_VALOR_INVALIDO BOOLEAN, SS_CIFRAS_RECIENTES BOOLEAN, SS_FACTOR_IPC_A_DIC2025 DECIMAL(7,6), SS_INGRESOS_BILLONES_COP_DIC2025 DOUBLE, SS_ACTIVOS_BILLONES_COP_DIC2025 DOUBLE, SS_INTENSIDAD_EXPORTADORA_PCT DOUBLE, N_RAZONES_SOCIALES_DIAN BIGINT, TIPO_CAMBIO_RAZON_SOCIAL VARCHAR, ES_COMERCIALIZADORA_INTERNACIONAL BOOLEAN, ES_TRASLADO_DOMICILIO BOOLEAN, ANIO_MATRICULA BIGINT, TRASLADO_EN_PERIODO BOOLEAN, MATRICULA_POSTERIOR_A_PRIMERA_EXPORTACION BOOLEAN, PRIMARY KEY(NIT), FOREIGN KEY (COD_MPIO_DIAN_DIRECCION_PROPIA) REFERENCES dim_municipio(COD_MPIO), FOREIGN KEY (COD_DEPTO_ORIGEN_PRINCIPAL) REFERENCES dim_departamento(COD_DEPTO));

-- @@ tabla exportador_pais
CREATE TABLE exportador_pais(NIT VARCHAR, COD_PAIS_DESTINO VARCHAR, FOB_USD DOUBLE, N_LINEAS BIGINT, PCT_FOB_NIT DOUBLE, RANKING_EN_NIT BIGINT, PRIMARY KEY(NIT, COD_PAIS_DESTINO), FOREIGN KEY (NIT) REFERENCES dim_exportador_analitica(NIT), FOREIGN KEY (COD_PAIS_DESTINO) REFERENCES dim_pais(COD_PAIS));

-- @@ tabla exportador_subpartida
CREATE TABLE exportador_subpartida(NIT VARCHAR, SUBPARTIDA VARCHAR, FOB_USD DOUBLE, N_LINEAS BIGINT, PCT_FOB_NIT DOUBLE, RANKING_EN_NIT BIGINT, PRIMARY KEY(NIT, SUBPARTIDA), FOREIGN KEY (NIT) REFERENCES dim_exportador_analitica(NIT), FOREIGN KEY (SUBPARTIDA) REFERENCES dim_subpartida(SUBPARTIDA));

-- @@ tabla panel_exportador_mes
CREATE TABLE panel_exportador_mes(NIT VARCHAR, PERIODO DATE, ANIO SMALLINT, MES TINYINT, FOB_USD DOUBLE, FOB_USD_VENTA_EXTERIOR DOUBLE, FOB_USD_NO_MINERO_ENERGETICO DOUBLE, FOB_USD_ORIGEN_ANTIOQUIA DOUBLE, PESO_NETO_KGS_ANALISIS DOUBLE, N_LINEAS BIGINT, N_DECLARACIONES BIGINT, N_PAISES BIGINT, N_SUBPARTIDAS BIGINT, N_LINEAS_ATIPICAS BIGINT, PRIMARY KEY(NIT, PERIODO), FOREIGN KEY (NIT) REFERENCES dim_exportador_analitica(NIT));

-- @@ vista catalogo_codigos
CREATE VIEW catalogo_codigos AS (SELECT 'CLASE_EXPORTADOR' AS DOMINIO, * FROM cat_clase_exportador) UNION ALL (((((SELECT 'MODO_TRANSPORTE' AS DOMINIO, * FROM cat_modo_transporte) UNION ALL (SELECT 'MODALIDAD_EXPORTACION' AS DOMINIO, * FROM cat_modalidad_exportacion)) UNION ALL ((SELECT 'UNIDAD_FISICA' AS DOMINIO, * FROM cat_unidad_fisica) UNION ALL (SELECT 'TIPO_IDENTIFICACION' AS DOMINIO, * FROM cat_tipo_identificacion))) UNION ALL (((SELECT 'TIPO_CERTIFICADO_ORIGEN' AS DOMINIO, * FROM cat_certificado_origen) UNION ALL (SELECT 'FORMA_PAGO' AS DOMINIO, * FROM cat_forma_pago)) UNION ALL ((SELECT 'COD_REGIMEN_CAN' AS DOMINIO, * FROM cat_regimen_can) UNION ALL (SELECT 'LUGAR_SALIDA' AS DOMINIO, * FROM cat_lugar_salida)))) UNION ALL (SELECT 'TIPO_USUARIO' AS DOMINIO, * FROM cat_tipo_usuario));

-- @@ vista vw_ciudad_comprador_por_completar
CREATE VIEW vw_ciudad_comprador_por_completar AS WITH x AS (SELECT v.NIT_EXPORTADOR AS NIT, v.RAZON_SOCIAL, v.COD_PAIS_DESTINO, v.PAIS_DESTINO, v.CIUDAD_DESTINATARIO, v.VALOR_FOB_USD, CASE  WHEN ((v.CIUDAD_DESTINATARIO IS NULL)) THEN ('Sin ciudad') WHEN ((v.CIUDAD_DESTINATARIO_NORM IS NULL)) THEN ('Sin letras') WHEN ((v.CIUDAD_DESTINATARIO ~~ '%�%')) THEN ('Caracteres dañados') WHEN (((v.COD_PAIS_DESTINO = 'USA') AND (v.CIUDAD_DESTINATARIO_NORM IN ('ALABAMA', 'ALASKA', 'ARIZONA', 'ARKANSAS', 'CALIFORNIA', 'COLORADO', 'CONNECTICUT', 'DELAWARE', 'FLORIDA', 'GEORGIA', 'HAWAII', 'IDAHO', 'ILLINOIS', 'INDIANA', 'IOWA', 'KANSAS', 'KENTUCKY', 'LOUISIANA', 'MAINE', 'MARYLAND', 'MASSACHUSETTS', 'MICHIGAN', 'MINNESOTA', 'MISSISSIPPI', 'MISSOURI', 'MONTANA', 'NEBRASKA', 'NEVADA', 'NEW HAMPSHIRE', 'NEW JERSEY', 'NEW MEXICO', 'NEW YORK', 'NORTH CAROLINA', 'NORTH DAKOTA', 'OHIO', 'OKLAHOMA', 'OREGON', 'PENNSYLVANIA', 'RHODE ISLAND', 'SOUTH CAROLINA', 'SOUTH DAKOTA', 'TENNESSEE', 'TEXAS', 'UTAH', 'VERMONT', 'VIRGINIA', 'WASHINGTON', 'WEST VIRGINIA', 'WISCONSIN', 'WYOMING')))) THEN ('Estado en vez de ciudad') WHEN (((upper(strip_accents(v.CIUDAD_DESTINATARIO_NORM)) = upper(strip_accents(v.PAIS_DESTINO))) AND (v.COD_PAIS_DESTINO NOT IN ('PAN', 'SGP', 'MEX', 'GTM', 'KWT', 'LUX', 'MCO', 'DJI', 'SMR', 'VAT', 'HKG', 'MAC', 'BRN')))) THEN ('País en vez de ciudad') ELSE NULL END AS PROBLEMA FROM vw_exportaciones AS v WHERE (v.ES_VENTA_EXTERIOR AND (v.NIT_EXPORTADOR IS NOT NULL)))SELECT NIT, RAZON_SOCIAL, count_star() AS N_LINEAS_POR_COMPLETAR, round(sum(VALOR_FOB_USD), 2) AS FOB_USD_POR_COMPLETAR, string_agg(DISTINCT PROBLEMA, '; ') AS PROBLEMAS, string_agg(DISTINCT PAIS_DESTINO, '; ') AS PAISES, string_agg(DISTINCT COALESCE(CIUDAD_DESTINATARIO, '(vacío)'), ' | ') AS VALORES_EN_FUENTE FROM x WHERE (PROBLEMA IS NOT NULL) GROUP BY 1, 2 ORDER BY FOB_USD_POR_COMPLETAR DESC;

-- @@ vista vw_directorio_antioquia
CREATE VIEW vw_directorio_antioquia AS SELECT * FROM dim_exportador_analitica WHERE ES_EXPORTADOR_ANTIOQUENO ORDER BY RANKING_ANTIOQUIA_FOB;

-- @@ vista vw_exportaciones
CREATE VIEW vw_exportaciones AS SELECT h.*, strftime(h.PERIODO, '%Y-%m') AS ANIO_MES, ((h.ANIO || '-T') || (((h.MES - 1) // 3) + 1)) AS TRIMESTRE, COALESCE(h.NUMERO_FORMULARIO, ('AE-' || h.NUM_AUTORIZACION_EMBARQUE), ('R-' || h.ID_REGISTRO)) AS ID_DECLARACION, ((NOT h.ES_DESTINO_ZONA_FRANCA) AND (h.COD_PAIS_DESTINO != 'COL')) AS ES_VENTA_EXTERIOR, (h.COD_DEPTO_ORIGEN != '00') AS DEPTO_ORIGEN_ASIGNADO, (h.COD_MODALIDAD_EXPORTACION IN ('198', '199')) AS ES_EXPORTACION_COMERCIAL, COALESCE(h.PESO_NETO_KGS_AJUSTADO, h.PESO_NETO_KGS) AS PESO_NETO_KGS_ANALISIS, COALESCE(h.PESO_BRUTO_KGS_AJUSTADO, h.PESO_BRUTO_KGS) AS PESO_BRUTO_KGS_ANALISIS, COALESCE(h.CANTIDAD_UNIDADES_FISICAS_AJUSTADA, h.CANTIDAD_UNIDADES_FISICAS) AS CANTIDAD_UNIDADES_FISICAS_ANALISIS, (h.VALOR_FOB_USD / "nullif"(h.PESO_NETO_KGS, 0)) AS PRECIO_USD_KG, (h.VALOR_FOB_USD / "nullif"(COALESCE(h.PESO_NETO_KGS_AJUSTADO, h.PESO_NETO_KGS), 0)) AS PRECIO_USD_KG_ANALISIS, (h.VALOR_FOB_USD / "nullif"(COALESCE(h.CANTIDAD_UNIDADES_FISICAS_AJUSTADA, h.CANTIDAD_UNIDADES_FISICAS), 0)) AS PRECIO_USD_UNIDAD_ANALISIS, sp.CAPITULO, sp.PARTIDA, sp.SUBPARTIDA_SA6, sp.SECTOR_EXPORTACION, sp.ES_MINERO_ENERGETICO, sp.ES_AGRICOLA_MADR, sp.PRODUCTO_AGRICOLA_MADR, sp.TRADICION_AGRICOLA_MADR, e.RAZON_SOCIAL, e.VINCULO_ANTIOQUIA, COALESCE(e.EMPRESA_ANTIOQUENA, CAST('f' AS BOOLEAN)) AS EMPRESA_ANTIOQUENA, COALESCE(e.ES_EXPORTADOR_ANTIOQUENO, CAST('f' AS BOOLEAN)) AS ES_EXPORTADOR_ANTIOQUENO, e.CAMARA_COMERCIO, e.CIIU_PRINCIPAL_RUES, e.SECTOR_EXPORTADOR_PRINCIPAL, m.CIUDAD_NORMALIZADA AS CIUDAD_DESTINATARIO_NORM, cl.DESCRIPCION AS CLASE_EXPORTADOR_DESC, dc.RAZON_SOCIAL_DECLARANTE, mu.MUNICIPIO AS MUNICIPIO_DIRECCION_DECLARADA, pd.PAIS AS PAIS_DESTINO, pd.TIPO_DESTINO, zf.ZONA_FRANCA AS ZONA_FRANCA_DESTINO, ad1.ADUANA AS ADUANA_DESPACHO, ad2.ADUANA AS ADUANA_SALIDA, ls.DESCRIPCION AS LUGAR_SALIDA, dp.DEPARTAMENTO AS DEPTO_PROCEDENCIA, dor.DEPARTAMENTO AS DEPTO_ORIGEN, mt.DESCRIPCION AS MODO_TRANSPORTE, pb.PAIS AS PAIS_BANDERA, mo.DESCRIPCION AS MODALIDAD_EXPORTACION, un.DESCRIPCION AS UNIDAD_FISICA, co.DESCRIPCION AS CERTIFICADO_ORIGEN, fp.DESCRIPCION AS FORMA_PAGO_DESC, rc.DESCRIPCION AS REGIMEN_CAN_DESC, tu.DESCRIPCION AS TIPO_USUARIO_DESC FROM hechos_analitica AS h INNER JOIN dim_subpartida AS sp ON ((sp.SUBPARTIDA = h.SUBPARTIDA)) LEFT JOIN dim_exportador_analitica AS e ON ((e.NIT = h.NIT_EXPORTADOR)) LEFT JOIN map_ciudad_destinatario AS m ON (((m.CIUDAD_DESTINATARIO = h.CIUDAD_DESTINATARIO) AND (m.COD_PAIS_DESTINO = h.COD_PAIS_DESTINO))) LEFT JOIN cat_clase_exportador AS cl ON ((cl.CODIGO = h.CLASE_EXPORTADOR)) LEFT JOIN dim_declarante AS dc ON ((dc.NIT_DECLARANTE = h.NIT_DECLARANTE)) LEFT JOIN dim_municipio AS mu ON ((mu.COD_MPIO = h.COD_MPIO_DIRECCION_DECLARADA)) LEFT JOIN dim_pais AS pd ON ((pd.COD_PAIS = h.COD_PAIS_DESTINO)) LEFT JOIN dim_zona_franca AS zf ON ((zf.COD_ZONA_FRANCA = h.COD_ZONA_FRANCA_DESTINO)) LEFT JOIN dim_aduana AS ad1 ON ((ad1.COD_ADUANA = h.COD_ADUANA_DESPACHO)) LEFT JOIN dim_aduana AS ad2 ON ((ad2.COD_ADUANA = h.COD_ADUANA_SALIDA)) LEFT JOIN cat_lugar_salida AS ls ON ((ls.CODIGO = h.COD_LUGAR_SALIDA)) LEFT JOIN dim_departamento AS dp ON ((dp.COD_DEPTO = h.COD_DEPTO_PROCEDENCIA)) LEFT JOIN dim_departamento AS dor ON ((dor.COD_DEPTO = h.COD_DEPTO_ORIGEN)) LEFT JOIN cat_modo_transporte AS mt ON ((mt.CODIGO = h.COD_MODO_TRANSPORTE)) LEFT JOIN dim_pais AS pb ON ((pb.COD_PAIS = h.COD_PAIS_BANDERA)) LEFT JOIN cat_modalidad_exportacion AS mo ON ((mo.CODIGO = h.COD_MODALIDAD_EXPORTACION)) LEFT JOIN cat_unidad_fisica AS un ON ((un.CODIGO = h.COD_UNIDAD_FISICA)) LEFT JOIN cat_certificado_origen AS co ON ((co.CODIGO = h.TIPO_CERTIFICADO_ORIGEN)) LEFT JOIN cat_forma_pago AS fp ON ((fp.CODIGO = h.FORMA_PAGO)) LEFT JOIN cat_regimen_can AS rc ON ((rc.CODIGO = h.COD_REGIMEN_CAN)) LEFT JOIN cat_tipo_usuario AS tu ON ((tu.CODIGO = h.TIPO_USUARIO));

-- @@ vista vw_exportaciones_antioquia
CREATE VIEW vw_exportaciones_antioquia AS SELECT * FROM vw_exportaciones WHERE (ORIGEN_MERCANCIA_ANTIOQUIA OR ES_EXPORTADOR_ANTIOQUENO);

-- @@ vista vw_exportaciones_origen_asignado
CREATE VIEW vw_exportaciones_origen_asignado AS SELECT * FROM vw_exportaciones WHERE DEPTO_ORIGEN_ASIGNADO;

-- @@ vista vw_serie_mensual
CREATE VIEW vw_serie_mensual AS SELECT ANIO_MES AS PERIODO, round((sum(VALOR_FOB_USD) FILTER (WHERE ORIGEN_MERCANCIA_ANTIOQUIA) / 1000000.0), 3) AS FOB_MUSD_ORIGEN_ANTIOQUIA, round((sum(VALOR_FOB_USD) FILTER (WHERE (ORIGEN_MERCANCIA_ANTIOQUIA AND (NOT ES_MINERO_ENERGETICO))) / 1000000.0), 3) AS FOB_MUSD_ORIGEN_ANTIOQUIA_NO_MINERO_ENERGETICO, round((sum(VALOR_FOB_USD) FILTER (WHERE (ORIGEN_MERCANCIA_ANTIOQUIA AND ES_AGRICOLA_MADR)) / 1000000.0), 3) AS FOB_MUSD_ORIGEN_ANTIOQUIA_AGRICOLA, round((sum(VALOR_FOB_USD) FILTER (WHERE EMPRESA_ANTIOQUENA) / 1000000.0), 3) AS FOB_MUSD_EMPRESAS_ANTIOQUENAS, round((sum(VALOR_FOB_USD) FILTER (WHERE ES_EXPORTADOR_ANTIOQUENO) / 1000000.0), 3) AS FOB_MUSD_EXPORTADORES_ANTIOQUENOS, round((sum(VALOR_FOB_USD) / 1000000.0), 3) AS FOB_MUSD_NACIONAL, round((sum(VALOR_FOB_USD) FILTER (WHERE (NOT ES_MINERO_ENERGETICO)) / 1000000.0), 3) AS FOB_MUSD_NACIONAL_NO_MINERO_ENERGETICO, round((sum(VALOR_FOB_USD) FILTER (WHERE ES_DESTINO_ZONA_FRANCA) / 1000000.0), 3) AS FOB_MUSD_NACIONAL_DESTINO_ZONA_FRANCA, count(DISTINCT NIT_EXPORTADOR) FILTER (WHERE EMPRESA_ANTIOQUENA) AS N_NIT_EMPRESAS_ANTIOQUENAS, count(DISTINCT NIT_EXPORTADOR) FILTER (WHERE ES_EXPORTADOR_ANTIOQUENO) AS N_NIT_EXPORTADORES_ANTIOQUENOS, count(DISTINCT NIT_EXPORTADOR) AS N_NIT_NACIONAL, round((sum(VALOR_FOB_USD) FILTER (WHERE ES_VENTA_EXTERIOR) / 1000000.0), 3) AS FOB_MUSD_VENTA_EXTERIOR, round((sum(VALOR_FOB_USD) FILTER (WHERE DEPTO_ORIGEN_ASIGNADO) / 1000000.0), 3) AS FOB_MUSD_ORIGEN_ASIGNADO, round((sum(PESO_NETO_KGS_ANALISIS) / 1000000.0), 3) AS PESO_NETO_MILES_T_ANALISIS FROM vw_exportaciones GROUP BY 1 ORDER BY 1;

-- @@ vista vw_validacion_dane
CREATE VIEW vw_validacion_dane AS SELECT r.PERIODO_REFERENCIA, round((sum(h.VALOR_FOB_USD) / 1000000.0), 1) AS BASE_FOB_MUSD, r.DANE_FOB_MUSD, round(((100 * ((sum(h.VALOR_FOB_USD) / 1000000.0) - r.DANE_FOB_MUSD)) / r.DANE_FOB_MUSD), 3) AS DIF_PCT, r.FUENTE, r.URL FROM ref_dane_publicaciones AS r INNER JOIN hechos_analitica AS h ON ((h.PERIODO BETWEEN r.PERIODO_DESDE AND r.PERIODO_HASTA)) GROUP BY r.PERIODO_REFERENCIA, r.DANE_FOB_MUSD, r.FUENTE, r.URL, r.PERIODO_DESDE, r.PERIODO_HASTA ORDER BY r.PERIODO_DESDE, r.PERIODO_HASTA DESC;

-- @@ vista vw_validacion_madr
CREATE VIEW vw_validacion_madr AS WITH d AS (SELECT h.ANIO, round((sum(h.VALOR_FOB_USD) FILTER (WHERE (s.ES_AGRICOLA_MADR AND (h.MES <= r.MESES))) / 1000000.0), 1) AS DIAN_AGRICOLA_NACIONAL_MUSD, round((sum(h.VALOR_FOB_USD) FILTER (WHERE (s.ES_AGRICOLA_MADR AND h.ORIGEN_MERCANCIA_ANTIOQUIA AND (h.MES <= r.MESES))) / 1000000.0), 1) AS DIAN_AGRICOLA_ANTIOQUIA_MUSD FROM hechos_analitica AS h INNER JOIN dim_subpartida AS s USING (SUBPARTIDA) INNER JOIN ref_madr_agricola_anual AS r ON ((r.ANIO = h.ANIO)) GROUP BY 1)SELECT d.ANIO, r.MESES, d.DIAN_AGRICOLA_NACIONAL_MUSD, r.MADR_AGRICOLA_NACIONAL_MUSD, d.DIAN_AGRICOLA_ANTIOQUIA_MUSD, r.MADR_AGRICOLA_ANTIOQUIA_MUSD FROM d INNER JOIN ref_madr_agricola_anual AS r USING (ANIO) ORDER BY 1;

-- @@ vista vw_validacion_mincit
CREATE VIEW vw_validacion_mincit AS WITH d AS (SELECT ((h.ANIO || 'Q') || (((h.MES - 1) // 3) + 1)) AS TRIMESTRE, round((sum(h.VALOR_FOB_USD) / 1000000.0)) AS DIAN_TOTAL_MUSD, round((sum(h.VALOR_FOB_USD) FILTER (WHERE (NOT s.ES_MINERO_ENERGETICO)) / 1000000.0)) AS DIAN_NME_MUSD FROM hechos_analitica AS h INNER JOIN dim_subpartida AS s USING (SUBPARTIDA) GROUP BY 1)SELECT d.*, r.MINCIT_TOTAL_MUSD, r.MINCIT_NME_MUSD, round(((100 * (d.DIAN_TOTAL_MUSD - r.MINCIT_TOTAL_MUSD)) / r.MINCIT_TOTAL_MUSD), 2) AS DIF_TOTAL_PCT, round(((100 * (d.DIAN_NME_MUSD - r.MINCIT_NME_MUSD)) / r.MINCIT_NME_MUSD), 2) AS DIF_NME_PCT FROM d LEFT JOIN ref_mincit_trimestral AS r USING (TRIMESTRE) ORDER BY 1;

-- @@ vista vw_ventas_exterior
CREATE VIEW vw_ventas_exterior AS SELECT * FROM vw_exportaciones WHERE ES_VENTA_EXTERIOR;
